import{c as e}from"./react-BYS6FseU.js";var t=e(),n=[{title:`1. About these terms`,body:[`These terms apply to every enquiry, quotation, booking and sale arranged by Jebri Safaris in Tanzania and Kenya. By sending us an enquiry or confirming a booking with us, you accept these terms on behalf of everyone travelling in your party.`,`Where a written quotation or itinerary we have issued you conflicts with these terms, that document takes priority for the trip it covers.`]},{title:`2. How a booking is confirmed`,body:[`A trip is confirmed once we have issued a written quotation and you have accepted it and paid the agreed deposit. Until then nothing is reserved, and availability shown on our site is indicative rather than held.`,`Prices are quoted per person and are based on the number of travellers, the season, and the accommodation level selected. They are recalculated if any of those change.`]},{title:`3. Payments and currency`,body:[`We accept payment by credit or debit card, PayPal and bank transfer, and we can quote in the major currencies shown on our site. A deposit confirms your booking; the balance is due 30 days before travel.`,`Prices are shown in United States Dollars unless a different currency is selected for display. The currency you are charged in is confirmed on your quotation. Where we quote in a currency other than your own, exchange-rate movements between quotation and payment can change the final amount.`]},{title:`4. What is included`,body:[`Each tour page lists what is included and what is not. Unless your quotation says otherwise, inclusions normally cover accommodation as described, meals on the stated board basis, all game drives and park entrance fees, and transfers between the points named in the itinerary.`,`Your specific quotation is the authoritative statement of what your trip includes. Where an itinerary varies by season or by availability, the confirmed quotation prevails over general website descriptions.`]},{title:`5. What is not included`,body:[`Unless stated otherwise, international flights, visas and travel insurance premiums, items of personal expenditure, drinks beyond those included, gratuities, and optional activities not listed in your itinerary are payable separately.`,`Comprehensive travel insurance is arranged for every traveller as part of the booking. Your policy certificate sets out the covered events, limits, exclusions and the claims process.`]},{title:`6. Changes and cancellation by you`,body:[`Cancellations are refunded according to how much notice you give us:`,`You can cancel up to 90 days before travel for a full refund of amounts paid, less any non-refundable park and lodge deposits already paid to suppliers.`,`Between 60 and 90 days, 75% is refunded.`,`Between 30 and 60 days, 50% is refunded.`,`Within 30 days of travel, no refund is due.`,`These are our default terms. They are separate from any travel insurance policy you hold, and cancellation claims under insurance remain subject to the insurer’s own terms and conditions.`]},{title:`7. Changes and cancellation by us`,body:[`Occasionally a lodge, camp or park service is unavailable, or conditions make an itinerary unsafe or impossible to run. If that happens we will offer a comparable alternative at no extra cost, or refund the portion of the trip affected.`,`If we cancel your trip for reasons within our control, refunds are calculated on the same scale set out in section 6.`]},{title:`8. Changes to the itinerary`,body:[`Game drives and lodge order are chosen each day according to where wildlife is actually seen. Routes and timings may change from those published, because that flexibility is what allows us to show you animals rather than follow a fixed timetable.`]},{title:`9. Health, safety and responsibility`,body:[`East Africa is generally safe, but you should follow your guide’s instructions at all times. You must not leave the vehicle on a game drive except where a walking safari has been specifically included, and you must stay behind park rules on distances from wildlife.`,`You are responsible for your own health and must declare any medical condition, allergy or mobility requirement before travelling so we can plan properly. Yellow fever vaccination is required if you are arriving from an endemic country.`,`We cannot be held liable for loss or injury caused by your own decisions, by failing to follow park or guide instructions, or by conditions outside our reasonable control. Our total liability is limited to the price you paid for the affected part of the trip.`]},{title:`10. Reviews and images`,body:[`Reviews you submit are published only after approval. You grant us permission to display the review text and rating you provided.`,`Photographs on this site are used under the licences credited alongside them. Images that depict a person, a vehicle or a location clearly identified in the caption are illustrative of the experience in general and are not a guarantee of what a specific departure will include.`]},{title:`11. Complaints`,body:[`If something went wrong, tell us while you are still travelling so we can put it right on the ground, or contact us within 28 days of your return. We aim to acknowledge every complaint within three working days.`]},{title:`12. Governing law`,body:[`These terms are governed by the laws of the jurisdiction in which our operating entity is registered, and disputes are subject to the exclusive jurisdiction of the competent courts of that jurisdiction.`]}];function r(){return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsxs)(`section`,{className:`relative bg-teal-800 text-cream-50 py-20 sm:py-24 overflow-hidden`,children:[(0,t.jsx)(`div`,{className:`absolute inset-0 bg-hero-vignette opacity-50 mix-blend-multiply`}),(0,t.jsx)(`div`,{className:`absolute inset-0 bg-[radial-gradient(circle_at_top_right,rgba(201,104,61,0.15),transparent_50%)]`}),(0,t.jsxs)(`div`,{className:`container-x text-center relative z-10`,children:[(0,t.jsx)(`span`,{className:`eyebrow text-terracotta-300 drop-shadow-sm`,children:`Legal`}),(0,t.jsx)(`h1`,{className:`font-display text-4xl sm:text-5xl md:text-6xl mt-4 animate-slide-up`,children:`Terms & Conditions`}),(0,t.jsx)(`p`,{className:`mt-4 text-cream-200/90 max-w-2xl mx-auto`,children:`The terms that apply when you enquire, book or travel with Jebri Safaris.`})]})]}),(0,t.jsx)(`section`,{className:`container-x py-20 max-w-3xl`,children:(0,t.jsxs)(`div`,{className:`glass-card p-6 sm:p-10`,children:[n.map((e,n)=>(0,t.jsxs)(`div`,{className:n?`mt-8`:``,children:[(0,t.jsx)(`h2`,{className:`font-display text-xl sm:text-2xl text-teal-800`,children:e.title}),e.body.map((e,n)=>(0,t.jsx)(`p`,{className:`mt-3 text-teal-700/85 leading-relaxed`,children:e},n))]},e.title)),(0,t.jsx)(`p`,{className:`mt-10 pt-6 border-t border-savanna-200 text-sm text-teal-600`,children:`Last updated 2 October 2026.`})]})})]})}export{r as default};